// MOCK mode only (npm run dev:mock). Loaded lazily, so it is never in a
// production bundle. The responses are real app/qc.py output generated by
// scripts/make_fixtures.py with meta.is_mock = true; the API is not called.
import scenarios from './scenarios.json'
import demoCsv from './demo.csv?raw'
import smallCsv from './small.csv?raw'
import emptyCsv from './empty.csv?raw'
import demo from './demo.responses.json'
import small from './small.responses.json'
import empty from './empty.responses.json'

const DATA = {
  demo: { csv: demoCsv, responses: demo },
  small: { csv: smallCsv, responses: small },
  empty: { csv: emptyCsv, responses: empty },
}

export const MOCK_SCENARIOS = scenarios

export const scenarioCsv = (name) => DATA[name].csv

/**
 * Pretend POST /analyze: return the scenario's precomputed response for the
 * requested reviewed_zones. The request's records are not analysed.
 */
export function mockAnalyze(req, scenario) {
  const key = [...new Set(req.reviewed_zones || [])].sort().join(',')
  const res = DATA[scenario]?.responses[key]
  if (!res) {
    const e = new Error(`MOCK has no response for scenario "${scenario}" with reviewed zones [${key}].`)
    e.status = 0
    throw e
  }
  return structuredClone(res)
}
